const raw=$json.control_snapshot;
const s=typeof raw==='string'?JSON.parse(raw):raw||{};
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusClass=(v)=>['healthy','degraded','blocked','unknown'].includes(String(v))?String(v):'unknown';
const fmtDate=(v)=>{ if(!v) return '—'; const d=new Date(v); return Number.isNaN(d.getTime())?'—':d.toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}); };
const runtime=s.runtime||{};
const business=s.business||{};
const connectors=Array.isArray(s.connectors)?s.connectors:[];
const components=Array.isArray(s.components)?s.components:[];
const alerts=Array.isArray(s.alerts)?s.alerts:[];
const connectorCards=connectors.map(c=>`<article class="card"><div class="row"><div><div class="eyebrow">${esc(c.connector_type||'connector')}</div><h3>${esc(c.display_name||c.connector_key)}</h3></div><span class="badge ${c.active?'healthy':'unknown'}">${c.active?'active':'safe-disabled'}</span></div><p class="muted">${esc(c.connector_key)}</p><p class="tiny">Updated ${esc(fmtDate(c.updated_at))}</p></article>`).join('');
const componentRows=components.map(c=>`<tr><td><strong>${esc(c.display_name||c.component_key)}</strong><div class="tiny">${esc(c.component_key)}</div></td><td><span class="badge ${statusClass(c.operational_status)}">${esc(c.operational_status)}</span></td><td>${esc(c.circuit_state||'—')}</td><td>${esc(c.failures_1h??0)}</td><td>${esc(c.open_dead_letters??0)}</td><td>${esc(fmtDate(c.last_success_at))}</td></tr>`).join('');
const alertHtml=alerts.length?alerts.map(a=>`<div class="alert"><div class="row"><strong>${esc(a.summary)}</strong><span class="badge ${a.severity==='critical'?'blocked':'degraded'}">${esc(a.severity)}</span></div><div class="tiny">${esc(a.component_key)} · ${esc(a.alert_type)} · ${esc(fmtDate(a.first_observed_at))}</div></div>`).join(''):'<div class="empty">No active observability alerts.</div>';
const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Revenue Intelligence Control Center</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
