</style></head><body><main class="shell"><div class="top"><div><div class="eyebrow">Agent V2 · Local Operations</div><h1>Revenue Intelligence Control Center</h1><p class="muted">${esc(business.company_name||'Revenue Intelligence Agent')} · ${esc(business.currency_code||'—')} · ${esc(business.timezone||'—')}</p></div><div class="actions"><a class="btn" href="./control">Refresh</a><a class="btn" href="/">Open n8n</a></div></div>
<section class="grid"><div class="metric"><div class="eyebrow">Overall status</div><div class="value"><span class="badge ${statusClass(runtime.overall_status)}">${esc(runtime.overall_status||'unknown')}</span></div></div><div class="metric"><div class="eyebrow">Governed KPIs</div><div class="value">${esc(s.active_kpi_count??0)}</div></div><div class="metric"><div class="eyebrow">Managed components</div><div class="value">${esc(runtime.component_count??0)}</div></div><div class="metric"><div class="eyebrow">Open dead letters</div><div class="value">${esc(runtime.open_dead_letters??0)}</div></div></section>
<section class="section"><h2>CRM & Source Connectors</h2><div class="connector-grid">${connectorCards||'<div class="empty">No connector registry rows found.</div>'}</div></section>
<section class="section panel"><div class="panel-head"><div><h2>Reliability & Observability</h2><div class="tiny">Observed ${esc(fmtDate(runtime.observed_at))}</div></div><div class="tiny">Failures 1h: ${esc(runtime.failures_1h??0)} · 24h: ${esc(runtime.failures_24h??0)}</div></div><div class="table-wrap"><table><thead><tr><th>Component</th><th>Status</th><th>Circuit</th><th>Failures 1h</th><th>Dead letters</th><th>Last success</th></tr></thead><tbody>${componentRows||'<tr><td colspan="6">No component status rows found.</td></tr>'}</tbody></table></div></section>
<section class="section panel"><div class="panel-head"><h2>Active Alerts</h2><span class="badge ${alerts.length?'degraded':'healthy'}">${alerts.length} alert${alerts.length===1?'':'s'}</span></div>${alertHtml}</section>
<div class="notice"><strong>Read-only control surface</strong><div class="muted">This dashboard uses the existing Reporting RO credential and exposes no workflow mutation, credential, SQL, activation, or connector-write action. It is intended for the local loopback deployment only; the public ingress does not route this path.</div></div><div class="tiny">Snapshot generated ${esc(fmtDate(s.generated_at))}</div></main></body></html>`;
return {html};
